// 29 Oct 2026: context (description) for the 5 keys tagged 2910. Guard: write only if the live description still equals what was read.
const NEW = {
  966223260: { old: 'Subtitle under the main heading of the Quality Improvement landing page.', desc: 'Subtitle under the main heading of the Quality Improvement landing page (AI tool that makes blurry or low-quality photos sharp and clean). "One button" = the user only clicks a single button, no settings or editing skills needed. "Comes back" = the improved photo is returned to the user. Short, friendly, informal tone.' },
  966223261: { old: 'Short trust badge under the hero heading (icon + text). Keep it short, no full stop.', desc: 'Short trust badge under the hero heading of the Quality Improvement landing page (icon + text, shown next to other badges). Means the photo is improved with a single click, no manual editing. Keep it short, no full stop.' },
  966223305: { old: 'FAQ answer, shown when the question is expanded.', desc: 'FAQ answer on the Quality Improvement landing page, shown when the question "Is it hard to use?" is expanded. Reassures the user that no skills are needed: they just upload a photo and the AI does the rest. Keep it short and casual.' },
  966223582: { old: 'SEO meta description of the Quality Improvement landing (snippet in Google results). Max 160 characters.', desc: 'SEO meta description of the Quality Improvement landing (snippet in Google results). Max 160 characters. The page offers an AI tool that turns blurry photos into sharp, clean ones. Keep the file formats JPG, PNG and WEBP as they are.' },
  968559220: { old: '', desc: 'Button label in the chat, shown while the AI is still processing the user\'s request (e.g. working on a photo or generating a reply). Clicking it stops the processing. Use a short verb as on a button, one word if possible.' }
};
const res = $input.first().json;
const keys = (res.body && res.body.keys) ? res.body.keys : [];
const upd = []; const skipped = [];
for (const k of keys) {
  const n = NEW[k.key_id];
  if (!n) { skipped.push({ id: k.key_id, reason: 'not in list' }); continue; }
  if ((k.description || '') !== n.old) { skipped.push({ id: k.key_id, reason: 'description changed since read', live: k.description }); continue; }
  upd.push({ key_id: k.key_id, description: n.desc });
}
if (upd.length !== 5) throw new Error('expected 5 writes, got ' + upd.length + ': ' + JSON.stringify(skipped));
return [{ json: { payload: { keys: upd }, count: upd.length, expected: NEW, skipped: skipped } }];

const b = $('Build Payload').first().json;
const u = $('Update Keys').first().json;
const body = u.body || {};
const back = $input.first().json.keys || [];
const check = [];
for (const k of back) {
  const e = b.expected[k.key_id];
  check.push({ id: k.key_id, ok: !!e && k.description === e.desc, description: k.description });
}
return [{ json: { sent: b.count, status: u.statusCode, updated: (body.keys || []).length, errors: body.errors || body.error || null, readback_ok: check.filter(function (c) { return c.ok; }).length, check: check } }];
